  /// < Trigger End-Of-Stream event for the corresponding appsrc and ignore the given input value. The corresponding appsrc will no longer accept new data after this.
  static const int ML_PIPELINE_BUF_SRC_EVENT_EOS = 65536;
}

/// @brief Enumeration for pipeline state.
