}

/// @brief Callback for the change of pipeline state.
/// @details If an application wants to get the change of pipeline state, use this callback. This callback can be registered when constructing the pipeline using ml_pipeline_construct(). Do not spend too much time in the callback.
/// @since_tizen 5.5
/// @param[in] state The new state of the pipeline.
/// @param[out] user_data User application's private data.
typedef ml_pipeline_state_cb
    = ffi.Pointer<ffi.NativeFunction<ml_pipeline_state_cbFunction>>;
typedef ml_pipeline_state_cbFunction = ffi.Void Function(
    ffi.Int32 state, ffi.Pointer<ffi.Void> user_data);
typedef Dartml_pipeline_state_cbFunction = void Function(
    int state, ffi.Pointer<ffi.Void> user_data);

/// @brief A handle of an NNStreamer pipeline.
/// @since_tizen 5.5
typedef ml_pipeline_h = ffi.Pointer<ffi.Void>;

/// @brief Callback for sink element of NNStreamer pipelines (pipeline's output).
/// @details If an application wants to accept data outputs of an NNStreamer stream, use this callback to get data from the stream. Note that the buffer may be deallocated after the return and this is synchronously called. Thus, if you need the data afterwards, copy the data to another buffer and return fast. Do not spend too much time in the callback. It is recommended to use very small tensors at sinks.
/// @since_tizen 5.5
/// @remarks The @a data can be used only in the callback. To use outside, make a copy.
/// @remarks The @a info can be used only in the callback. To use outside, make a copy.
/// @param[in] data The handle of the tensor output of the pipeline (a single frame. tensor/tensors). Number of tensors is determined by ml_tensors_info_get_count() with the handle 'info'. Note that the maximum number of tensors is #ML_TENSOR_SIZE_LIMIT.
/// @param[in] info The handle of tensors information (cardinality, dimension, and type of given tensor/tensors).
/// @param[in,out] user_data User application's private data.
typedef ml_pipeline_sink_cb
    = ffi.Pointer<ffi.NativeFunction<ml_pipeline_sink_cbFunction>>;
typedef ml_pipeline_sink_cbFunction = ffi.Void Function(
    ml_common.ml_tensors_data_h data,
    ml_common.ml_tensors_info_h info,
    ffi.Pointer<ffi.Void> user_data);
typedef Dartml_pipeline_sink_cbFunction = void Function(
    ml_common.ml_tensors_data_h data,
    ml_common.ml_tensors_info_h info,
    ffi.Pointer<ffi.Void> user_data);

/// @brief A handle of a "sink node" of an NNStreamer pipeline.
/// @since_tizen 5.5
typedef ml_pipeline_sink_h = ffi.Pointer<ffi.Void>;

/// @brief A handle of a "src node" of an NNStreamer pipeline.
/// @since_tizen 5.5
typedef ml_pipeline_src_h = ffi.Pointer<ffi.Void>;

/// @brief Callbacks for src input events.
/// @details A set of callbacks that can be installed on the appsrc with ml_pipeline_src_set_event_cb().
/// @since_tizen 6.5
final class ml_pipeline_src_callbacks_s extends ffi.Struct {
  /// < Called when the appsrc needs more data. User may submit a buffer via ml_pipeline_src_input_data() from this thread or another thread. length is just a hint and when it is set to -1, any number of bytes can be pushed into appsrc.
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Void Function(
              ml_pipeline_src_h src_handle,
              ffi.UnsignedInt length,
              ffi.Pointer<ffi.Void> user_data)>> need_data;

  /// < Called when appsrc has enough data. It is recommended that the application stops calling push-buffer until the need_data callback is emitted again to avoid excessive buffer queueing.
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Void Function(ml_pipeline_src_h src_handle,
              ffi.Pointer<ffi.Void> user_data)>> enough_data;

  /// < Called when a seek should be performed to the offset. The next push-buffer should produce buffers from the new offset . This callback is only called for seekable stream types.
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Void Function(ml_pipeline_src_h src_handle, ffi.Uint64 offset,
              ffi.Pointer<ffi.Void> user_data)>> seek_data;
}

